/**
 * Numbered page controls for paged lists (`design/components/pagination.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/pagination.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  PAGINATION_ELLIPSIS,
  Ref,
  agentMember,
  cell,
  derived,
  elementRef,
  mountEffect,
  paginationWindow,
  useMember,
  watchEffect,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/pagination.module.css'
import { Button, type ButtonProps } from '../controls/Button'
import { Inline, type InlineProps } from '../layout/Inline'

export type SiblingCount = NonNullable<PaginationProps['siblingCount']>

export interface PaginationMessages {
  previous: string
  next: string
  page: (page: number) => string
}

/** Numbered page controls for paged lists: the inputs it takes, by the React member's prop names. */
export interface PaginationProps {
  /**
   * The app holds the pager while it does something else to the list: every control is disabled,
   * the current page too, and no page is asked for.
   */
  disabled?: boolean
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: PaginationMessages
  /**
   * 1-based and controlled, because the current page belongs to the list.
   */
  page: number
  pageCount: number
  siblingCount?: 1 | 2
}

/** Numbered page controls for paged lists. */
@Component({
  selector: 'pm-pagination',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Button, Inline],
  // prettier-ignore
  template: `@if (e1()) {<nav
[attr.class]="e2()"
[attr.aria-label]="e3()"
[attr.data-disabled]="e4()"
tabindex="-1"
data-member="pagination"
(focusin)="h1($event)"
(focusout)="h2($event)"
[pmRef]="root"
><pm-inline
[gap]="e5()"
align="center"
[wrap]="e6()"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e7()"
icon="previous"
[label]="e8()"
[disabled]="e9()"
(click)="h3()"
></pm-button>
@for (entry of e10(); track e11(entry, $index); let at = $index) {@if (e12(entry)) {<span
[attr.class]="e13(entry)"
aria-hidden="true"
>…</span>} @else {<pm-button
[variant]="e14(entry)"
[tone]="e15(entry)"
size="sm"
[current]="e16(entry)"
[label]="e17(entry)"
[aria-label]="e18(entry)"
[disabled]="e19(entry)"
(click)="h4(entry)"
></pm-button>}}
<pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e7()"
icon="next"
[label]="e20()"
[disabled]="e21()"
(click)="h5()"
></pm-button></pm-inline></nav>}`,
})
export class Pagination {
  /**
   * The app holds the pager while it does something else to the list: every control is disabled,
   * the current page too, and no page is asked for.
   */
  readonly disabled = input<
    Exclude<PaginationProps['disabled'], undefined>,
    PaginationProps['disabled']
  >(false, {
    transform: (value: PaginationProps['disabled']) => (value === undefined ? false : value),
  })
  readonly label = input<Exclude<PaginationProps['label'], undefined>, PaginationProps['label']>(
    'Pagination',
    {
      transform: (value: PaginationProps['label']) => (value === undefined ? 'Pagination' : value),
    },
  )
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  readonly messages = input<
    Exclude<PaginationProps['messages'], undefined>,
    PaginationProps['messages']
  >((() => ({ previous: 'Previous page', next: 'Next page', page: (page) => `Page ${page}` }))(), {
    transform: (value: PaginationProps['messages']) =>
      value === undefined
        ? (() => ({
            previous: 'Previous page',
            next: 'Next page',
            page: (page) => `Page ${page}`,
          }))()
        : value,
  })
  /**
   * 1-based and controlled, because the current page belongs to the list.
   */
  readonly page = input.required<PaginationProps['page']>()
  readonly pageCount = input.required<PaginationProps['pageCount']>()
  readonly siblingCount = input<
    Exclude<PaginationProps['siblingCount'], undefined>,
    PaginationProps['siblingCount']
  >(1, { transform: (value: PaginationProps['siblingCount']) => (value === undefined ? 1 : value) })
  readonly onPageChange = output<number>({ alias: 'pageChange' })
  protected readonly $ = useMember({
    events: ['pageChange'],
    props: {
      disabled: () => this.disabled(),
      label: () => this.label(),
      messages: () => this.messages(),
      page: () => this.page(),
      pageCount: () => this.pageCount(),
      siblingCount: () => this.siblingCount(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly focused = cell(() => null as HTMLElement | null)
  protected readonly taken = cell(() => null as string | number | null)
  protected readonly root = elementRef<HTMLElement>()
  protected readonly entries = derived(() =>
    paginationWindow(this.$p.page, this.$p.pageCount, this.$p.siblingCount),
  )
  protected readonly controls = derived(() => [
    'previous',
    ...this.entries.value.filter((shown) => shown !== PAGINATION_ELLIPSIS),
    'next',
  ])
  protected readonly focusIn = derived(() => (event: FocusEvent) => {
    this.focused.value = event.target as HTMLElement
  })
  protected readonly focusOut = derived(() => (event: FocusEvent) => {
    if (!(event.target as HTMLElement).matches(':disabled')) this.focused.value = null
  })
  protected readonly keepPlace = derived(() => () => {
    const pager = this.root.value as HTMLElement | null
    if (pager === null) return
    const names: readonly (string | number)[] = this.controls.value
    if (!this.$p.disabled) {
      const control = this.taken.value
      this.taken.value = null
      if (control === null || document.activeElement !== pager) return
      const button = [...pager.querySelectorAll('button')][names.indexOf(control)]
      if (button !== undefined && !button.matches(':disabled')) button.focus()
      return
    }
    const from = this.focused.value as HTMLElement | null
    if (from === null || !from.isConnected || !from.matches(':disabled')) return
    const active = document.activeElement
    if (active !== from && active !== null && active !== document.body) return
    this.taken.value =
      names[[...pager.querySelectorAll('button')].indexOf(from as HTMLButtonElement)] ?? null
    pager.focus()
  })
  private release1: (() => void) | undefined
  private release3: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    watchEffect(
      () => this.entries.value.length > 0,
      () => this.effect1(),
      true,
    )
    watchEffect(
      () => this.$p.disabled,
      () => this.effect2(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  protected e1() {
    return this.entries.value.length > 0
  }

  protected e2() {
    if (!(this.entries.value.length > 0)) return undefined as never
    return styles.pagination
  }

  protected e3() {
    if (!(this.entries.value.length > 0)) return undefined as never
    return this.$p.label
  }

  protected e4() {
    if (!(this.entries.value.length > 0)) return undefined as never
    return this.$p.disabled ? '' : undefined
  }

  protected h1($event: FocusEvent): void {
    if (!(this.entries.value.length > 0)) return
    this.focusIn.value($event)
  }

  protected h2($event: FocusEvent): void {
    if (!(this.entries.value.length > 0)) return
    this.focusOut.value($event)
  }

  protected e5(): InlineProps['gap'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    return 1
  }

  protected e6(): InlineProps['wrap'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    return true
  }

  protected e7(): ButtonProps['iconOnly'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    return true
  }

  protected e8(): ButtonProps['label'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    return this.$p.messages.previous
  }

  protected e9(): ButtonProps['disabled'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    return this.$p.disabled || this.$p.page <= 1
  }

  protected h3(): void {
    if (!(this.entries.value.length > 0)) return
    this.$.emit(this.onPageChange, 'onPageChange', this.$p.page - 1)
  }

  e10() {
    if (!(this.entries.value.length > 0)) return undefined as never
    return this.entries.value
  }

  protected e11(entry: Each<ReturnType<Pagination['e10']>>, at: number) {
    return entry === PAGINATION_ELLIPSIS ? `gap-${at}` : entry
  }

  protected e12(entry: Each<ReturnType<Pagination['e10']>>) {
    if (!(this.entries.value.length > 0)) return undefined as never
    return entry === PAGINATION_ELLIPSIS
  }

  protected e13(entry: Each<ReturnType<Pagination['e10']>>) {
    if (!(this.entries.value.length > 0)) return undefined as never
    if (!(entry === PAGINATION_ELLIPSIS)) return undefined as never
    return styles.ellipsis
  }

  protected e14(entry: Each<ReturnType<Pagination['e10']>>): ButtonProps['variant'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    if (entry === PAGINATION_ELLIPSIS) return undefined as never
    return entry === this.$p.page ? 'soft' : 'ghost'
  }

  protected e15(entry: Each<ReturnType<Pagination['e10']>>): ButtonProps['tone'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    if (entry === PAGINATION_ELLIPSIS) return undefined as never
    return entry === this.$p.page ? 'accent' : 'neutral'
  }

  protected e16(entry: Each<ReturnType<Pagination['e10']>>): ButtonProps['current'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    if (entry === PAGINATION_ELLIPSIS) return undefined as never
    return entry === this.$p.page
  }

  protected e17(entry: Each<ReturnType<Pagination['e10']>>): ButtonProps['label'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    if (entry === PAGINATION_ELLIPSIS) return undefined as never
    return String(entry)
  }

  protected e18(entry: Each<ReturnType<Pagination['e10']>>): ButtonProps['aria-label'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    if (entry === PAGINATION_ELLIPSIS) return undefined as never
    return this.$p.messages.page(entry)
  }

  protected e19(entry: Each<ReturnType<Pagination['e10']>>): ButtonProps['disabled'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    if (entry === PAGINATION_ELLIPSIS) return undefined as never
    return this.$p.disabled
  }

  protected h4(entry: Each<ReturnType<Pagination['e10']>>): void {
    if (!(this.entries.value.length > 0)) return
    if (entry === PAGINATION_ELLIPSIS) return
    if (entry !== this.$p.page) {
      this.$.emit(this.onPageChange, 'onPageChange', entry)
    }
  }

  protected e20(): ButtonProps['label'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    return this.$p.messages.next
  }

  protected e21(): ButtonProps['disabled'] {
    if (!(this.entries.value.length > 0)) return undefined as never
    return this.$p.disabled || this.$p.page >= this.$p.pageCount
  }

  protected h5(): void {
    if (!(this.entries.value.length > 0)) return
    this.$.emit(this.onPageChange, 'onPageChange', this.$p.page + 1)
  }

  private effect1(): void {
    this.release1?.()
    const run = () => {
      this.keepPlace.value()
    }
    const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
    for (const element of [this.root.value])
      if (element)
        mutation?.observe(element, {
          childList: true,
          characterData: true,
          subtree: true,
          attributeFilter: ['disabled'],
        })
    this.release1 = () => {
      mutation?.disconnect()
    }
    run()
  }

  private effect2(): void {
    this.keepPlace.value()
  }

  private effect3(): void {
    this.release3?.()
    const ran = agentMember({
      member: 'Pagination',
      element: () => this.root.value,
      state: () => ({
        page: this.$p.page,
        'page-count': this.$p.pageCount,
        disabled: this.$p.disabled,
      }),
      actions: {
        set: {
          argument: 'number',
          run: (value) =>
            (() => {
              if (!Number.isInteger(value) || value < 1 || value > this.$p.pageCount) {
                throw new Error(
                  `There is no page ${value}; the pages run from 1 to ${this.$p.pageCount}.`,
                )
              }
              if (value !== this.$p.page) this.$.emit(this.onPageChange, 'onPageChange', value)
            })(),
        },
      },
      withholds: () => this.root.value,
    })
    this.release3 = () => {
      ran()
    }
  }
}
